"""Launch robot_state_publisher + move_group for the simple 3-joint arm.

All MoveIt parameters are loaded by hand from ../urdf and ../config so that
this setup does not need to be built/installed as an ament package.
"""

from pathlib import Path

import yaml
from launch import LaunchDescription
from launch_ros.actions import Node

PROJECT_ROOT = Path(__file__).resolve().parent.parent


def load_file(relative_path: str) -> str:
    return (PROJECT_ROOT / relative_path).read_text()


def load_yaml(relative_path: str) -> dict:
    return yaml.safe_load(load_file(relative_path))


def generate_launch_description():
    robot_description = {"robot_description": load_file("urdf/simple_arm.urdf")}
    robot_description_semantic = {
        "robot_description_semantic": load_file("config/simple_arm.srdf")
    }
    robot_description_kinematics = {
        "robot_description_kinematics": load_yaml("config/kinematics.yaml")
    }
    robot_description_planning = {
        "robot_description_planning": load_yaml("config/joint_limits.yaml")
    }

    ompl_config = load_yaml("config/ompl_planning.yaml")
    planning_pipelines = {
        "planning_pipelines": ["ompl"],
        "default_planning_pipeline": "ompl",
        "ompl": ompl_config,
    }

    trajectory_execution = {
        "allow_trajectory_execution": False,
        "moveit_manage_controllers": False,
    }

    planning_scene_monitor_parameters = {
        "publish_planning_scene": True,
        "publish_geometry_updates": True,
        "publish_state_updates": True,
        "publish_transforms_updates": True,
    }

    move_group_capabilities = {
        "capabilities": "",
        "disable_capabilities": "",
    }

    robot_state_publisher_node = Node(
        package="robot_state_publisher",
        executable="robot_state_publisher",
        name="robot_state_publisher",
        output="screen",
        parameters=[robot_description],
    )

    joint_state_publisher_node = Node(
        package="joint_state_publisher",
        executable="joint_state_publisher",
        name="joint_state_publisher",
        output="screen",
        parameters=[robot_description],
    )

    move_group_node = Node(
        package="moveit_ros_move_group",
        executable="move_group",
        name="move_group",
        output="screen",
        parameters=[
            robot_description,
            robot_description_semantic,
            robot_description_kinematics,
            robot_description_planning,
            planning_pipelines,
            trajectory_execution,
            planning_scene_monitor_parameters,
            move_group_capabilities,
        ],
    )

    return LaunchDescription(
        [
            robot_state_publisher_node,
            joint_state_publisher_node,
            move_group_node,
        ]
    )

